PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?agent a pv:Agent ;
           pv:areaOfExpertise prodi:prod-cat-Sensor .
  BIND(?agent AS ?result)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?service a pv:Service ;
           pv:price ?price .
  ?price pv:amount ?amount .
  FILTER(?amount = (SELECT MAX(?maxAmount) WHERE { 
    ?s a pv:Service ; 
         pv:price ?p . 
    ?p pv:amount ?maxAmount .
  }))
} LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  VALUES ?lcd_inductor { prodi:hw-U990-5234138 prodi:hw-V178-8820348 prodi:hw-V285-7238338 }
  ?result pv:compatibleProduct ?lcd_inductor .
  ?result a pv:Product ; pv:id ?id .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?supplierName ?country ?priceAmount WHERE {
  ?hardware a pv:Hardware ;
              pv:hasSupplier ?supplier ;
              pv:price ?price .
  ?supplier pv:name ?supplierName ;
            pv:country ?country .
  ?price pv:amount ?priceAmount .
} ORDER BY DESC(?priceAmount) LIMIT 5 OFFSET 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?lightestProduct ?heaviestProduct WHERE {
  ?hardware a pv:Hardware ;
              pv:hasCategory ?category ;
              pv:weight_g ?weight .

  # Find the lightest product in each category
  {
    SELECT ?category (MIN(?weight) AS ?minWeight) WHERE {
      ?hardware a pv:Hardware ;
                  pv:hasCategory ?category ;
                  pv:weight_g ?weight .
    } GROUP BY ?category
  }

  # Find the heaviest product in each category
  {
    SELECT ?category (MAX(?weight) AS ?maxWeight) WHERE {
      ?hardware a pv:Hardware ;
                  pv:hasCategory ?category ;
                  pv:weight_g ?weight .
    } GROUP BY ?category
  }

  FILTER(?weight = ?minWeight)
  ?lightestProduct a pv:Hardware ;
                   pv:hasCategory ?category ;
                   pv:weight_g ?minWeight .

  FILTER(?weight = ?maxWeight)
  ?heaviestProduct a pv:Hardware ;
                    pv:hasCategory ?category ;
                    pv:weight_g ?maxWeight .
} GROUP BY ?category ?lightestProduct ?heaviestProduct

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?product ?compatibleProduct ?priceDifference WHERE {
  ?product a pv:Product ;
           pv:compatibleProduct ?compatibleProduct ;
           pv:price [ pv:amount ?productPrice ] .
  ?compatibleProduct pv:price [ pv:amount ?compatibleProductPrice ] .
  BIND(?productPrice - ?compatibleProductPrice AS ?priceDifference)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?employeeName ?email ?phone ?departmentName ?directReportName WHERE {
  ?employee a pv:Employee ;
            pv:name ?employeeName ;
            pv:email ?email ;
            pv:phone ?phone ;
            pv:memberOf ?department .
  ?department pv:name ?departmentName .
  OPTIONAL { ?employee pv:hasDirectReport ?directReport .
             ?directReport pv:name ?directReportName . }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?supplier) AS ?result) WHERE {
  VALUES ?strainEncoder { prodi:hw-K367-1320550 prodi:hw-F383-6450755 prodi:hw-N704-3896920 }
  ?compatibleProduct pv:compatibleProduct ?strainEncoder .
  ?compatibleProduct pv:hasSupplier ?supplier .
}
